generated_pydough:
num_distinct_colleges_crew = match_season.teams.WHERE(
    name == 'Columbus Crew'
).CALCULATE(
    number_of_different_colleges = NDISTINCT(match_seasons.college)
)

chiltern_trains = routes.WHERE(
    station.local_authority == "Chiltern"
).CALCULATE(
    name=train.name,
    time=train.time
)

yale_players_avg_height = colleges.WHERE(
    name_full == "Yale University"
).CALCULATE(
    avg_height = AVG(player_colleges.player.height)
)

brown_account_balances = account.WHERE(
    name == "Brown"
).CALCULATE(
    checking_balance=checkings.SINGULAR().balance,
    saving_balance=saving.SINGULAR().balance
)

# Count total food allergy records (not distinct students)
result = allergy_1.CALCULATE(
    total_food_allergies = COUNT(
        has_allergies.WHERE(allergy_type.allergytype == "food")
    )
)

top_staff_by_complaints = staffs.WHERE(
    HAS(complaint) == 1
).CALCULATE(
    staff_first_name=first_name,
    complaint_count=COUNT(complaint)
).TOP_K(5, by=complaint_count).CALCULATE(
    first_name=staff_first_name
)

defender_draft_info = match_season.match_seasons.WHERE(
    position == 'Defender'
).CALCULATE(
    player_draft_pick_number=draft_pick_number,
    player_draft_class=draft_class
)

# Find the customer who ordered the least amount of goods and get their payment method
customer_with_least_orders = customer.WHERE(
    HAS(customer_order.order_item) == 1
).CALCULATE(
    customer_name=customer_name,
    payment_method=payment_method,
    total_quantity=SUM(customer_order.order_item.order_quantity)
).TOP_K(1, by=total_quantity.ASC()).CALCULATE(
    payment_method=payment_method
)

# Calculate the average savings balance across all savings accounts
avg_savings_balance = small_bank_1.CALCULATE(
    avg_savings=AVG(saving.balance)
)

# Find checking balances for people with above-average savings
result = avg_savings_balance.saving.WHERE(
    balance > avg_savings
).account.checkings.CALCULATE(
    checking_balance=balance
)

# Find students who have taken prerequisites for International Finance
students_with_prereqs = courses.WHERE(
    title == "International Finance"
).prereqs.course.sections.take.student.CALCULATE(
    student_name=name
)

teacher_course_counts = teachers.WHERE(
    HAS(course_arranges)==1
).CALCULATE(
    Name=name,
    COUNT_STAR=COUNT(course_arranges)
).ORDER_BY(Name.ASC())

# Find the maximum fastest lap speed in Monaco Grand Prix 2008
max_speed_monaco_2008 = race.WHERE(
    (year == 2008) & (name == 'Monaco Grand Prix')
).CALCULATE(
    max_fastest_lap_speed = MAX(result.fastestlapspeed)
)

graduates_2004_sfsu = campuse.WHERE(
    campus == "San Francisco State University"
).CALCULATE(
    total_graduates=SUM(discipline_enrollment.WHERE(year == 2004).graduate)
)

# Find catalog contents with length below 3 or width above 5
catalog_contents_filtered = product_catalog.catalog_content.WHERE(
    (length < "3") | (width > "5")
).CALCULATE(
    catalog_entry_name=catalog_entry_name
)
